{
  T * pT = (T*)this;
  pT->Lock();
  IUnknown ** pp = m_vec.begin();
  while (pp < m_vec.end())
  {
    if (*pp != NULL)
    {
      m_EventIntfObj.Attach(*pp);
      m_EventIntfObj.Refreshed();
      m_EventIntfObj.Attach(0);
    }
    pp++;
  }
  pT->Unlock();
}

