// Event Interface : _DEC15ROIEvents
// *********************************************************************//
template <class T>
class TEvents_EC15ROI : public IConnectionPointImpl<T,
                                                 &DIID__DEC15ROIEvents,
                                                 CComUnkArray<CONNECTIONPOINT_ARRAY_SIZE> >
{
public:
  void            Fire_Refreshed(void);
protected:
  _DEC15ROIEventsDisp m_EventIntfObj;
};

template <class T> void
TEvents_EC15ROI<T>::Fire_Refreshed(void)
{
  T * pT = (T*)this;
  pT->Lock();
  IUnknown ** pp = m_vec.begin();
  while (pp < m_vec.end())
  {
    if (*pp != NULL)
    {
      m_EventIntfObj.Attach(*pp);
      m_EventIntfObj.Refreshed();
      m_EventIntfObj.Attach(0);
    }
    pp++;
  }
  pT->Unlock();
}

